import { spawnSync } from 'node:child_process';
const cases = [
  ['--a','1','--b','1','--c','--'],
  ['--a','1','--b','1','--c=--'],
  ['--a','1','--b','1','--c','A','--'],
  ['--a','1','--b','1','--c','--','A'],
  ['--','--a','1','--b','1','--c','A'],
  ['--a','1','--b','1','--c','-'],
];
for (const argv of cases) {
  const r = spawnSync('/workspace/dataset/test14_executable', argv, {encoding:'utf8', timeout:10000});
  const j = spawnSync(process.execPath, ['/output/test14.mjs', ...argv], {encoding:'utf8', timeout:10000});
  const clean = s => (s||'').split('\n').filter(l=>!l.startsWith('[PYI-')).join('\n');
  const same = r.stdout===j.stdout && r.status===j.status && clean(r.stderr)===j.stderr;
  console.log((same?'PASS ':'FAIL ')+JSON.stringify(argv));
  if (!same) {
    console.log('  ref  rc='+r.status+' out='+JSON.stringify(r.stdout)+' err='+JSON.stringify(clean(r.stderr)));
    console.log('  port rc='+j.status+' out='+JSON.stringify(j.stdout)+' err='+JSON.stringify(j.stderr));
  }
}
EOF
cd /tmp/refute14 && node /tmp/refute14/drv.mjs

