  ['--a','--','--b','1','--c','A'],
  ['--a','1','--b','--','--c','A'],
  ['--c','--','--a','1','--b','1'],
  ['--a','1','--b','1','--c','--','--'],
  ['--h','--a','1','--b','1','--c','--'],
];
const clean = s => (s||'').split('\n').filter(l=>!l.startsWith('[PYI-')).join('\n');
const norm = s => clean(s).replace(/test14_executable/g,'PROG').replace(/test14\.mjs/g,'PROG');
for (const argv of cases) {
  const r = spawnSync('/workspace/dataset/test14_executable', argv, {encoding:'utf8', timeout:10000});
  const j = spawnSync(process.execPath, ['/output/test14.mjs', ...argv], {encoding:'utf8', timeout:10000});
  const same = r.stdout===j.stdout && r.status===j.status && norm(r.stderr)===norm(j.stderr);
  console.log((same?'PASS ':'FAIL ')+JSON.stringify(argv));
  if (!same) {
    console.log('  ref  rc='+r.status+' err='+JSON.stringify(norm(r.stderr)));
    console.log('  port rc='+j.status+' err='+JSON.stringify(norm(j.stderr)));
  }
}
EOF
